class Solution:

	def buildLowestNumber(self, S, k):
		st = []
		st.append(int(S[0]))
		length = len(S)
		for i in range(1, length):
			num = int(S[i])
			while len(st) != 0 and k > 0 and (num < st[-1]):
				st.pop()
				k = k - 1
			st.append(num)
		while len(st) != 0 and k > 0:
			st.pop()
			k = k - 1
		ans = ''
		li = list(map(str, st))
		while li and li[0] == '0':
			li.pop(0)
		if li:
			ans = ''.join(li)
			return ans
		return '0'
